import requests
import json
from datetime import datetime, timedelta

# System health monitoring
system_status = {
    'timestamp': datetime.now().isoformat(),
    'overall_health': 'healthy',
    'services': {},
    'workflow_stats': {},
    'alerts': [],
    'daily_summary': {}
}

# Check critical workflows (simulated - replace with actual n8n API calls)
workflows_to_check = [
    'QB Invoice Processing Hub',
    'QB Expense Automation Engine', 
    'QB Client Onboarding Orchestrator'
]

for workflow in workflows_to_check:
    try:
        # Simulate workflow health check
        # In production, you'd call n8n API to check workflow status
        workflow_health = {
            'status': 'active',
            'last_execution': datetime.now() - timedelta(minutes=random.randint(5, 60)),
            'success_rate': 0.95,
            'executions_today': random.randint(10, 50),
            'avg_execution_time': f"{random.randint(15, 120)}s"
        }
        system_status['services'][workflow] = workflow_health
    except Exception as e:
        system_status['services'][workflow] = {'status': 'error', 'error': str(e)}
        system_status['alerts'].append(f"Workflow '{workflow}' health check failed: {e}")

# Check external service connectivity
external_services = {
    'QuickBooks API': 'https://sandbox-quickbooks.api.intuit.com/v3/company/test/items',
    'OpenAI API': 'https://api.openai.com/v1/models',
    'Notion API': 'https://api.notion.com/v1/users/me'
}

for service, endpoint in external_services.items():
    try:
        # Simulate API health check (replace with actual API calls using proper auth)
        service_health = {
            'status': 'online',
            'response_time': f"{random.randint(50, 300)}ms",
            'last_check': datetime.now().isoformat()
        }
        system_status['services'][service] = service_health
    except Exception as e:
        system_status['services'][service] = {'status': 'offline', 'error': str(e)}
        system_status['alerts'].append(f"Service '{service}' is offline: {e}")

# Calculate daily summary stats
today = datetime.now().date()
system_status['daily_summary'] = {
    'total_invoices_processed': random.randint(15, 45),
    'total_expenses_processed': random.randint(25, 75),
    'new_clients_onboarded': random.randint(1, 5),
    'total_api_calls': random.randint(500, 1500),
    'avg_processing_time': f"{random.randint(30, 90)}s",
    'error_rate': f"{random.uniform(0.5, 5.0):.1f}%"
}

# Determine overall health
offline_services = [name for name, info in system_status['services'].items() 
                   if info.get('status') in ['error', 'offline']]

if len(offline_services) > 2:
    system_status['overall_health'] = 'critical'
    system_status['alerts'].append(f"Multiple services offline: {', '.join(offline_services)}")
elif len(offline_services) > 0:
    system_status['overall_health'] = 'degraded'
    system_status['alerts'].append(f"Some services offline: {', '.join(offline_services)}")

# Add performance alerts
if system_status['daily_summary']['total_api_calls'] > 1200:
    system_status['alerts'].append("High API usage detected - approaching rate limits")

if float(system_status['daily_summary']['error_rate'].replace('%', '')) > 3.0:
    system_status['alerts'].append("Error rate above normal threshold")

return system_status

